# ============================================================
# WIRING
# ============================================================

def _seed_for(subject, i):
    return i * 31 + sum(ord(c) for c in subject)


def _build_subject(subject, ws_list):
    out = []
    for i, (title, items) in enumerate(ws_list, start=1):
        out.append(ws(subject, i, title, items, _seed_for(subject, i)))
    return out


if __name__ == '__main__':
    all_worksheets = (
        _build_subject('Language', LANGUAGE_WORKSHEETS) +
        _build_subject('Math', MATH_WORKSHEETS) +
        _build_subject('Science', SCIENCE_WORKSHEETS) +
        _build_subject('History', HISTORY_WORKSHEETS)
    )
    write_worksheets(8, all_worksheets)
